#!/bin/sh
# Prints the Homebrew cask of Watt's Up. Usage: cask.rb.sh <version> <sha256> <owner/repo>
set -eu
version=$1
sha=$2
repo=$3
cat <<CASK
# typed: false
# frozen_string_literal: true

# Generated by apple/release.sh in https://github.com/$repo: do not edit by hand.
cask "wattsup" do
  version "$version"
  sha256 "$sha"

  url "https://github.com/$repo/releases/download/v#{version}/WattsUp-#{version}.zip"
  name "Watt's Up"
  desc "Watch UPSes served by NUT servers from the menu bar"
  homepage "https://github.com/$repo"

  depends_on macos: ">= :sonoma"

  app "Watt's Up.app"
  binary "#{appdir}/Watt's Up.app/Contents/MacOS/wattsup"

  # A menu bar app keeps running the old binary if the bundle is swapped under it.
  uninstall quit: "fr.nicoladmin.wattsup"

  zap trash: [
    "~/.config/wattsup",
    "~/Library/Preferences/fr.nicoladmin.wattsup.plist",
  ]
end
CASK
